		MainFrame.Position = UDim2.new(0.5, -240, 0.5, -135)
		UIState.MainWindowLastPosition = MainFrame.Position
		MainFrame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
		MainFrame.BackgroundTransparency = 0.10
